# backend.py
import os
import uuid
import json
import time
import threading
import tempfile
import subprocess
import requests
import base64
from datetime import datetime
from dataclasses import dataclass, asdict, field
from typing import List, Dict, Optional, Any
from flask import Flask, request, jsonify, send_file, Response
from werkzeug.utils import secure_filename
from werkzeug.datastructures import FileStorage
import shutil
import wave
import numpy as np
from io import BytesIO

app = Flask(__name__)

@dataclass
class TranscriptSegment:
    id: str
    start: float
    end: float
    en_text: str
    hu_text: str = ""
    emotions: List[str] = field(default_factory=list)

@dataclass
class DubbingJob:
    job_id: str
    status: str = "pending"
    created_at: float = field(default_factory=time.time)
    updated_at: float = field(default_factory=time.time)
    video_file: Optional[str] = None
    video_url: Optional[str] = None
    audio_file: Optional[str] = None
    segments: List[TranscriptSegment] = field(default_factory=list)
    tts_audio: Optional[str] = None
    localized_audio: Optional[str] = None
    fusion_audio: Optional[str] = None
    error_message: Optional[str] = None
    progress: int = 0
    current_step: str = "waiting"
    api_keys: Dict[str, str] = field(default_factory=dict)
    settings: Dict[str, Any] = field(default_factory=dict)
    temp_dir: Optional[str] = None

jobs: Dict[str, DubbingJob] = {}
MAX_FILE_SIZE = 2 * 1024 * 1024 * 1024  # 2GB
ALLOWED_EXTENSIONS = {'mp4', 'webm', 'mkv', 'mov', 'avi'}

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

def cleanup_job(job_id: str):
    job = jobs.get(job_id)
    if job and job.temp_dir:
        try:
            shutil.rmtree(job.temp_dir)
        except:
            pass
    if job_id in jobs:
        del jobs[job_id]

def create_temp_dir():
    temp_dir = tempfile.mkdtemp()
    os.makedirs(os.path.join(temp_dir, 'segments'), exist_ok=True)
    os.makedirs(os.path.join(temp_dir, 'tts'), exist_ok=True)
    os.makedirs(os.path.join(temp_dir, 'localized'), exist_ok=True)
    os.makedirs(os.path.join(temp_dir, 'fusion'), exist_ok=True)
    return temp_dir

def extract_audio(video_path: str, output_path: str, job: DubbingJob):
    cmd = [
        'ffmpeg', '-y', '-i', video_path,
        '-vn', '-acodec', 'pcm_s16le', '-ar', '16000', '-ac', '1',
        output_path
    ]
    result = subprocess.run(cmd, capture_output=True, timeout=300)
    if result.returncode != 0:
        raise Exception(f"FFmpeg audio extraction failed: {result.stderr.decode()}")

def download_video(url: str, output_path: str, job: DubbingJob):
    response = requests.get(url, stream=True, timeout=300)
    response.raise_for_status()
    with open(output_path, 'wb') as f:
        for chunk in response.iter_content(chunk_size=8192):
            f.write(chunk)

def transcribe_audio(audio_path: str, api_key: str, job: DubbingJob):
    job.progress = 10
    job.current_step = "stt"
    job.updated_at = time.time()

    url = ""
    with open(audio_path, 'rb') as f:
        files = {'file': f}
        data = {
            'language': 'en',
            'response_format': 'verbose_json',
            'timestamp_granularities[]': ['segment']
        }
        headers = {'Authorization': f'Bearer {api_key}'}
        response = requests.post(url, files=files, data=data, headers=headers, timeout=300)

    response.raise_for_status()
    result = response.json()

    segments = []
    for i, segment in enumerate(result.get('segments', [])):
        seg = TranscriptSegment(
            id=str(i),
            start=segment['start'],
            end=segment['end'],
            en_text=segment['text'].strip()
        )
        segments.append(seg)

    job.segments = segments
    job.progress = 20
    job.updated_at = time.time()

def translate_segments(segments: List[TranscriptSegment], api_key: str, job: DubbingJob):
    job.progress = 25
    job.current_step = "translation"
    job.updated_at = time.time()

    prompt = """Fordítsd le az alábbi angol szövegrészeket magyarra. Tartalmazd meg a stílust, hangvételt. Jelöld a prosódiai elemeket ezekkel a tokenekkel:
- [NEVETÉS] nevetéshez
- [SZÜNET] szünethez  
- [HANGSÚLY] hangsúlyos részekhez
- [FELKIÁLTÁS] felkiáltáshoz
- [KÉRDÉS] kérdő hangsúlyhoz

Formátum: Minden sor egy szegmens, csak a fordítást írd, semmilyen magyarázatot!

Példa:
Angol: Hello! How are you?
Magyar: Szia! [HANGSÚLY]Hogy vagy?[/HANGSÚLY]"""

    en_text = "\n".join([f"Szegmens {i}: {seg.en_text}" for i, seg in enumerate(segments)])
    full_prompt = f"{prompt}\n\n{en_text}"

    url = ""
    headers = {
        'x-api-key': api_key,
        'anthropic-version': '2023-06-01',
        'content-type': 'application/json'
    }
    data = {
        'model': 'claude-3-5-sonnet-20240620',
        'max_tokens': 4000,
        'messages': [{'role': 'user', 'content': full_prompt}]
    }

    response = requests.post(url, json=data, headers=headers, timeout=120)
    response.raise_for_status()
    result = response.json()

    content = result['content'][0]['text']
    lines = content.strip().split('\n')

    emotion_map = {
        '[NEVETÉS]': 'laugh',
        '[SZÜNET]': 'pause', 
        '[HANGSÚLY]': 'emphasis',
        '[FELKIÁLTÁS]': 'exclamation',
        '[KÉRDÉS]': 'question'
    }

    for i, line in enumerate(lines[:len(segments)]):
        if i < len(segments):
            hu_text = line.strip()
            emotions = []
            for token, emotion in emotion_map.items():
                if token in hu_text:
                    emotions.append(emotion)
            segments[i].hu_text = hu_text
            segments[i].emotions = emotions

    job.progress = 30
    job.updated_at = time.time()

def generate_tts_pipeline(job: DubbingJob):
    job.progress = 40
    job.current_step = "tts_pipeline"
    job.updated_at = time.time()

    tts_segments_dir = os.path.join(job.temp_dir, 'tts')

    # Voice cloning - first 30 seconds of original audio
    voice_sample_path = job.audio_file
    clone_url = ""
    with open(voice_sample_path, 'rb') as f:
        files = {'audio': f}
        data = {'name': 'cloned_voice'}
        headers = {'Authorization': f'Bearer {job.api_keys["tts"]}'}
        response = requests.post(clone_url, files=files, data=data, headers=headers)

    voice_id = response.json()['voice_id']

    segment_audios = []
    for i, segment in enumerate(job.segments):
        tts_text = segment.hu_text

        url = ""
        headers = {
            'Authorization': f'Bearer {job.api_keys["tts"]}',
            'Content-Type': 'application/json'
        }
        data = {
            'voice_id': voice_id,
            'text': tts_text,
            'speed': 1.0,
            'language': 'hu'
        }

        if segment.emotions:
            data['emotion'] = segment.emotions[0] if segment.emotions[0] in ['neutral', 'happy', 'sad', 'angry'] else 'neutral'

        response = requests.post(url, json=data, headers=headers)
        audio_data = response.content

        segment_path = os.path.join(tts_segments_dir, f"seg_{i}.wav")
        with open(segment_path, 'wb') as f:
            f.write(audio_data)
        segment_audios.append(segment_path)

    # Concatenate segments
    tts_output = os.path.join(job.temp_dir, 'tts_output.wav')
    concatenate_audio_files(segment_audios, tts_output, sample_rate=16000)
    job.tts_audio = tts_output
    job.progress = 60
    job.updated_at = time.time()

def generate_localization_pipeline(job: DubbingJob):
    job.progress = 65
    job.current_step = "localization_pipeline"
    job.updated_at = time.time()

    local_segments_dir = os.path.join(job.temp_dir, 'localized')

    # Voice profile creation
    profile_url = ""
    headers = {'Authorization': f'Bearer {job.api_keys["localizer"]}'}
    data = {'name': 'source_voice'}

    with open(job.audio_file, 'rb') as f:
        files = {'clip': f}
        response = requests.post(profile_url, files=files, data=data, headers=headers)

    voice_profile_id = response.json()['voice_id']

    segment_audios = []
    for i, segment in enumerate(job.segments):
        # Extract original segment audio
        orig_seg_path = os.path.join(job.temp_dir, f"orig_seg_{i}.wav")
        cmd = [
            'ffmpeg', '-y', '-i', job.audio_file,
            '-ss', str(segment.start), '-t', str(segment.end - segment.start),
            '-vn', '-acodec', 'pcm_s16le', '-ar', '16000', '-ac', '1',
            orig_seg_path
        ]
        subprocess.run(cmd, check=True)

        url = ""  # Note: requires project_id
        data = {
            'voice_uuid': voice_profile_id,
            'text': segment.hu_text,
            'target_language': 'hu'
        }
        files = {'source_audio': open(orig_seg_path, 'rb')}

        response = requests.post(url, files=files, data=data, headers=headers)
        audio_data = response.content

        segment_path = os.path.join(local_segments_dir, f"seg_{i}.wav")
        with open(segment_path, 'wb') as f:
            f.write(audio_data)
        segment_audios.append(segment_path)

    localized_output = os.path.join(job.temp_dir, 'localized_output.wav')
    concatenate_audio_files(segment_audios, localized_output, sample_rate=16000)
    job.localized_audio = localized_output
    job.progress = 80
    job.updated_at = time.time()

def fuse_audio_tracks(tts_path: str, localized_path: str, job: DubbingJob):
    job.progress = 85
    job.current_step = "fusion"
    job.updated_at = time.time()

    fusion_dir = os.path.join(job.temp_dir, 'fusion')

    tts_audio, sr_tts = load_audio(tts_path)
    loc_audio, sr_loc = load_audio(localized_path)

    # Ensure same length
    min_len = min(len(tts_audio), len(loc_audio))
    tts_audio = tts_audio[:min_len]
    loc_audio = loc_audio[:min_len]

    fused_audio = np.zeros_like(tts_audio)

    for i, segment in enumerate(job.segments):
        seg_start = int(i * min_len / len(job.segments))
        seg_end = int((i+1) * min_len / len(job.segments))
        seg_tts = tts_audio[seg_start:seg_end]
        seg_loc = loc_audio[seg_start:seg_end]

        if segment.emotions and ('laugh' in segment.emotions or 'emphasis' in segment.emotions):
            # Prefer localized for emotional segments
            fused_seg = seg_loc * 0.8 + seg_tts * 0.2
        else:
            # Prefer TTS for neutral
            fused_seg = seg_tts * 0.9 + seg_loc * 0.1

        # Normalize
        if len(fused_seg) > 0:
            fused_seg = fused_seg / np.max(np.abs(fused_seg)) * 0.9

        fused_audio[seg_start:seg_end] = fused_seg

    fusion_output = os.path.join(job.temp_dir, 'fusion_output.wav')
    save_audio(fused_audio, fusion_output, sample_rate=16000)
    job.fusion_audio = fusion_output
    job.progress = 95
    job.updated_at = time.time()

def load_audio(file_path: str):
    with wave.open(file_path, 'rb') as wav_file:
        frames = wav_file.readframes(wav_file.getnframes())
        audio = np.frombuffer(frames, dtype=np.int16).astype(np.float32) / 32768.0
        return audio, wav_file.getframerate()

def save_audio(audio: np.ndarray, file_path: str, sample_rate: int):
    audio = (audio * 32767).astype(np.int16)
    with wave.open(file_path, 'wb') as wav_file:
        wav_file.setnchannels(1)
        wav_file.setsampwidth(2)
        wav_file.setframerate(sample_rate)
        wav_file.writeframes(audio.tobytes())

def concatenate_audio_files(segment_paths: List[str], output_path: str, sample_rate: int):
    all_audio = []
    for path in segment_paths:
        audio, sr = load_audio(path)
        # Pad or trim to maintain timing
        expected_samples = int((float(os.path.basename(path).split('_')[1].split('.')[0]) * sample_rate))
        if len(audio) < expected_samples:
            audio = np.pad(audio, (0, expected_samples - len(audio)))
        elif len(audio) > expected_samples:
            audio = audio[:expected_samples]
        all_audio.append(audio)

    full_audio = np.concatenate(all_audio)
    save_audio(full_audio, output_path, sample_rate)

def process_job(job_id: str):
    job = jobs[job_id]
    try:
        job.status = "processing"
        job.progress = 5
        job.current_step = "extracting_audio"
        job.updated_at = time.time()

        if job.video_url:
            video_path = os.path.join(job.temp_dir, 'input_video.mp4')
            download_video(job.video_url, video_path, job)
            job.video_file = video_path
        elif job.video_file:
            filename = secure_filename(job.video_file.filename)
            video_path = os.path.join(job.temp_dir, filename)
            job.video_file.save(video_path)
            job.video_file = video_path

        job.audio_file = os.path.join(job.temp_dir, 'extracted_audio.wav')
        extract_audio(job.video_file, job.audio_file, job)

        transcribe_audio(job.audio_file, job.api_keys['stt'], job)
        translate_segments(job.segments, job.api_keys['translator'], job)
        generate_tts_pipeline(job)
        generate_localization_pipeline(job)
        fuse_audio_tracks(job.tts_audio, job.localized_audio, job)

        job.status = "completed"
        job.progress = 100
        job.current_step = "done"
        job.updated_at = time.time()

    except Exception as e:
        job.status = "error"
        job.error_message = str(e)
        job.progress = 0
        job.updated_at = time.time()

    # Schedule cleanup
    threading.Timer(3600.0, lambda: cleanup_job(job_id)).start()

@app.route('/create_job', methods=['POST'])
def create_job():
    try:
        temp_dir = create_temp_dir()
        job_id = str(uuid.uuid4())

        settings = {}
        if 'settings' in request.form:
            settings = json.loads(request.form['settings'])

        job = DubbingJob(
            job_id=job_id,
            temp_dir=temp_dir,
            settings=settings
        )

        if 'file' in request.files:
            file = request.files['file']
            if file.filename == '':
                return jsonify({'error': 'No file selected'}), 400
            if not allowed_file(file.filename):
                return jsonify({'error': 'Invalid file type'}), 400
            if file.content_length and file.content_length > MAX_FILE_SIZE:
                return jsonify({'error': 'File too large'}), 400

            job.video_file = file
        elif 'video_url' in request.form:
            url = request.form['video_url']
            if not url.startswith(('http://', 'https://')):
                return jsonify({'error': 'Invalid URL'}), 400
            job.video_url = url
        else:
            return jsonify({'error': 'No video source provided'}), 400

        jobs[job_id] = job
        return jsonify({'job_id': job_id})

    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/start_dubbing/<job_id>', methods=['POST'])
def start_dubbing(job_id):
    job = jobs.get(job_id)
    if not job:
        return jsonify({'error': 'Job not found'}), 404

    data = request.get_json()
    if not data or 'api_keys' not in data:
        return jsonify({'error': 'Missing API keys'}), 400

    job.api_keys = data['api_keys']
    job.status = 'queued'

    thread = threading.Thread(target=process_job, args=(job_id,))
    thread.daemon = True
    thread.start()

    return jsonify({'status': 'started', 'job_id': job_id})

@app.route('/status/<job_id>')
def get_status(job_id):
    job = jobs.get(job_id)
    if not job:
        return jsonify({'error': 'Job not found'}), 404

    return jsonify({
        'job_id': job.job_id,
        'status': job.status,
        'progress': job.progress,
        'current_step': job.current_step,
        'elapsed_seconds': int(time.time() - job.created_at),
        'error_message': job.error_message,
        'segments': [asdict(seg) for seg in job.segments] if job.segments else None
    })

@app.route('/download/tts/<job_id>')
def download_tts(job_id):
    job = jobs.get(job_id)
    if not job or not job.tts_audio:
        return jsonify({'error': 'TTS audio not ready'}), 404

    return send_file(job.tts_audio, mimetype='audio/wav', as_attachment=True, download_name='tts_hungarian.wav')

@app.route('/download/localized/<job_id>')
def download_localized(job_id):
    job = jobs.get(job_id)
    if not job or not job.localized_audio:
        return jsonify({'error': 'Localized audio not ready'}), 404

    return send_file(job.localized_audio, mimetype='audio/wav', as_attachment=True, download_name='localized_hungarian.wav')

@app.route('/download/fusion/<job_id>')
def download_fusion(job_id):
    job = jobs.get(job_id)
    if not job or not job.fusion_audio:
        return jsonify({'error': 'Fusion audio not ready'}), 404

    return send_file(job.fusion_audio, mimetype='audio/wav', as_attachment=True, download_name='fusion_hungarian.wav')

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000, debug=False, threaded=True)
