                <p style="color: #666; margin-top: 10px;">MP4, WebM, MKV, MOV (max 2GB)</p>
                <input type="file" id="fileInput" accept="video/*" style="display: none;">
            </div>
            <div id="fileInfo" style="display: none;">
                <p><strong id="fileName"></strong></p>
                <div class="progress-bar"><div class="progress-fill" id="uploadProgress"></div></div>
                <p id="uploadStatus"></p>
            </div>
            <div style="text-align: center; margin-top: 30px;">
                <p>Vagy add meg a videó URL-jét:</p>
                <input type="text" id="videoUrl" placeholder="" style="width: 500px;">
