        <div id="step4" class="step card">
            <h2>⬇️ Letöltések</h2>
            <div class="download-section">
                <div>
                    <h3>TTS Pipeline (Cartesia)</h3>
                    <audio id="ttsPlayer" class="audio-player" controls></audio>
                    <br><button onclick="downloadAudio('tts')" id="ttsDownload" disabled>💾 Letöltés</button>
                </div>
                <div>
                    <h3>Hangátvitel (Resemble)</h3>
                    <audio id="localizedPlayer" class="audio-player" controls></audio>
                    <br><button onclick="downloadAudio('localized')" id="localizedDownload" disabled>💾 Letöltés</button>
                </div>
