                <label>Max videó hossz (perc)</label>
                <input type="number" id="maxDuration" value="60" min="1" max="120">
            </div>
            <div style="display: flex; gap: 20px; margin-top: 20px;">
                <label><input type="checkbox" id="enableFusion" checked> Automatikus fúzió</label>
                <label><input type="checkbox" id="keepOriginal"> Eredeti hang megtartása</label>
            </div>
            <div style="text-align: right; margin-top: 20px;">
                <button onclick="saveSettings()">Mentés</button>
                <button onclick="closeSettings()">Bezárás</button>
            </div>
        </div>
    </div>

    <div id="errorContainer" class="error" style="display: none;"></div>

    <script>
        let currentJobId = null;
        let pollingInterval = null;
        let selectedFile = null;
        let backendUrl = '';

        // Load saved data
        window.onload = function() {
            loadApiKeys();
            loadSettings();
            setupDragDrop();
        };

        function showError(message) {
            const container = document.getElementById('errorContainer');
            container.textContent = message;
            container.style.display = 'block';
            setTimeout(() => container.style.display = 'none', 10000);
        }

        function showStep(stepNum) {
            document.querySelectorAll('.step').forEach(s => s.classList.remove('active'));
            document.getElementById(`step${stepNum}`).classList.add('active');
        }

        function loadApiKeys() {
            const keys = ['sttKey', 'translatorKey', 'ttsKey', 'localizerKey'];
            keys.forEach(key => {
                const value = localStorage.getItem(key);
                if (value) document.getElementById(key).value = value;
            });
        }

        function saveApiKeys() {
            const keys = ['sttKey', 'translatorKey', 'ttsKey', 'localizerKey'];
            let allFilled = true;
            keys.forEach(key => {
                const value = document.getElementById(key).value.trim();
                localStorage.setItem(key, value);
                if (!value) allFilled = false;
            });
            if (allFilled) {
                showStep(2);
            } else {
                showError('Minden API kulcs megadása kötelező!');
            }
        }

        function setupDragDrop() {
            const uploadArea = document.getElementById('uploadArea');
            const fileInput = document.getElementById('fileInput');

            ['dragenter', 'dragover', 'dragleave', 'drop'].forEach(eventName => {
                uploadArea.addEventListener(eventName, preventDefaults, false);
            });

            function preventDefaults(e) {
                e.preventDefault();
                e.stopPropagation();
            }

            ['dragenter', 'dragover'].forEach(eventName => {
                uploadArea.addEventListener(eventName, highlight, false);
            });

            ['dragleave', 'drop'].forEach(eventName => {
                uploadArea.addEventListener(eventName, unhighlight, false);
            });

            uploadArea.addEventListener('drop', handleDrop, false);
            uploadArea.addEventListener('click', () => fileInput.click());
            fileInput.addEventListener('change', handleFileSelect);

            function highlight(e) {
                uploadArea.classList.add('dragover');
            }

            function unhighlight(e) {
                uploadArea.classList.remove('dragover');
            }

            function handleDrop(e) {
                const dt = e.dataTransfer;
                const files = dt.files;
                handleFiles(files);
            }

            function handleFileSelect(e) {
                const files = e.target.files;
                handleFiles(files);
            }

            function handleFiles(files) {
                if (files.length > 0) {
                    selectedFile = files[0];
                    if (selectedFile.size > 2 * 1024 * 1024 * 1024) {
                        showError('A fájl mérete meghaladja a 2GB limitet!');
                        return;
                    }
                    document.getElementById('fileName').textContent = selectedFile.name;
                    document.getElementById('fileInfo').style.display = 'block';
                    document.getElementById('startDubbingBtn').disabled = false;
                }
            }
        }

        async function startDubbing() {
            const videoUrl = document.getElementById('videoUrl').value.trim();
            if (!selectedFile && !videoUrl) {
                showError('Válassz videót vagy add meg az URL-t!');
                return;
            }

            try {
                const formData = new FormData();
                const settings = await getSettings();
                formData.append('settings', JSON.stringify(settings));

                if (selectedFile) {
                    formData.append('file', selectedFile);
                } else {
                    formData.append('video_url', videoUrl);
                }

                const response = await fetch(`${backendUrl}/create_job`, {
                    method: 'POST',
                    body: formData
                });

                const data = await response.json();
                if (response.ok) {
                    currentJobId = data.job_id;
                    showStep(3);
                    pollStatus();
                } else {
                    showError(data.error || 'Hiba a feladat létrehozása közben');
                }
            } catch (error) {
                showError('Hálózati hiba: ' + error.message);
            }
        }

        function getApiKeys() {
            return {
                stt: localStorage.getItem('sttKey'),
                translator: localStorage.getItem('translatorKey'),
                tts: localStorage.getItem('ttsKey'),
                localizer: localStorage.getItem('localizerKey')
            };
        }

        async function pollStatus() {
            if (pollingInterval) clearInterval(pollingInterval);

            pollingInterval = setInterval(async () => {
                await checkStatus();
            }, 2000);

            await checkStatus();
        }

        async function checkStatus() {
            if (!currentJobId) return;

            try {
                const response = await fetch(`${backendUrl}/status/${currentJobId}`);
                const data = await response.json();

                if (!response.ok) {
                    showError(data.error);
                    return;
                }

                document.getElementById('currentStatus').textContent = 
                    data.status === 'completed' ? '✅ Kész!' : 
                    data.status === 'error' ? '❌ Hiba!' : '⏳ Feldolgozás...';

                document.getElementById('processingProgress').style.width = data.progress + '%';
                document.getElementById('progressText').textContent = data.progress + '%';

                const elapsed = new Date(data.elapsed_seconds * 1000).toISOString().substr(11, 8);
                document.getElementById('elapsedTime').textContent = elapsed;
                document.getElementById('currentStep').textContent = getStepName(data.current_step);

                if (data.error_message) {
                    showError(data.error_message);
                }

                if (data.segments && data.segments.length > 0) {
                    renderSegments(data.segments);
                }

                if (data.status === 'completed') {
                    clearInterval(pollingInterval);
                    setupDownloads();
                    showStep(4);
                } else if (data.status === 'error') {
                    clearInterval(pollingInterval);
                }

            } catch (error) {
                console.error('Status check failed:', error);
            }
        }

        function getStepName(step) {
            const steps = {
                'waiting': 'Várakozás...',
                'extracting_audio': 'Hang kinyerése...',
                'stt': 'Feliratozás...',
                'translation': 'Fordítás...',
                'tts_pipeline': 'TTS generálás...',
                'localization_pipeline': 'Hangátvitel...',
                'fusion': 'Összefúzió...',
                'done': 'Kész!'
            };
            return steps[step] || step;
        }

        function renderSegments(segments) {
            const container = document.getElementById('segmentsContainer');
            container.style.display = 'block';
            container.innerHTML = segments.map(seg => `
                <div class="segment">
                    <div class="timecode">${formatTime(seg.start)} - ${formatTime(seg.end)}</div>
                    <div><strong>EN:</strong> ${seg.en_text}</div>
                    <div><strong>HU:</strong> ${seg.hu_text}</div>
                    ${seg.emotions.length > 0 ? `
                        <div class="emotions">
                            ${seg.emotions.map(e => `<span class="emotion-tag ${e}">${e.toUpperCase()}</span>`).join('')}
                        </div>
                    ` : ''}
                </div>
            `).join('');
        }

        function formatTime(seconds) {
            const mins = Math.floor(seconds / 60);
            const secs = Math.floor(seconds % 60);
            return `${mins}:${secs.toString().padStart(2, '0')}`;
        }

        async function setupDownloads() {
            const audioUrls = {
                tts: `${backendUrl}/download/tts/${currentJobId}`,
                localized: `${backendUrl}/download/localized/${currentJobId}`,
                fusion: `${backendUrl}/download/fusion/${currentJobId}`
            };

            // Set audio sources
            document.getElementById('ttsPlayer').src = audioUrls.tts;
            document.getElementById('localizedPlayer').src = audioUrls.localized;
            document.getElementById('fusionPlayer').src = audioUrls.fusion;

            // Enable download buttons
            document.getElementById('ttsDownload').disabled = false;
            document.getElementById('localizedDownload').disabled = false;
            document.getElementById('fusionDownload').disabled = false;
        }

        async function downloadAudio(type) {
            const url = `${backendUrl}/download/${type}/${currentJobId}`;
            const link = document.createElement('a');
            link.href = url;
            link.download = `${type}_hungarian.wav`;
            link.click();
        }

        function goBack() {
            if (currentJobId) {
                if (confirm('Biztosan megszakítod a feldolgozást?')) {
                    clearInterval(pollingInterval);
                    currentJobId = null;
                }
            }
            showStep(2);
        }

        function newJob() {
            currentJobId = null;
            selectedFile = null;
            document.getElementById('fileInfo').style.display = 'none';
            document.getElementById('segmentsContainer').style.display = 'none';
            document.getElementById('startDubbingBtn').disabled = true;
            document.querySelectorAll('audio').forEach(a => {
                a.src = '';
                a.load();
            });
            document.querySelectorAll('[id$="Download"]').forEach(b => b.disabled = true);
            showStep(1);
        }

        // Settings modal
        function openSettings() {
            loadSettings();
            document.getElementById('settingsModal').style.display = 'block';
        }

        function closeSettings() {
            document.getElementById('settingsModal').style.display = 'none';
        }

        function loadSettings() {
            document.getElementById('maxDuration').value = localStorage.getItem('maxDuration') || 60;
            document.getElementById('enableFusion').checked = localStorage.getItem('enableFusion') !== 'false';
            document.getElementById('keepOriginal').checked = localStorage.getItem('keepOriginal') === 'true';
        }

        function saveSettings() {
            localStorage.setItem('maxDuration', document.getElementById('maxDuration').value);
            localStorage.setItem('enableFusion', document.getElementById('enableFusion').checked);
            localStorage.setItem('keepOriginal', document.getElementById('keepOriginal').checked);
            closeSettings();
        }

        async function getSettings() {
            return {
                max_duration: parseInt(document.getElementById('maxDuration').value),
                fusion_enabled: document.getElementById('enableFusion').checked,
                keep_original: document.getElementById('keepOriginal').checked
            };
        }

        // Global modal close on outside click
        window.onclick = function(event) {
            const modal = document.getElementById('settingsModal');
            if (event.target === modal) {
                closeSettings();
            }
        }
    </script>
</body>
</html>
