```python
import os
import uuid
import json
import time
import threading
import tempfile
import subprocess
import requests
import shutil
import wave
import numpy as np
from dataclasses import dataclass, asdict, field
from typing import List, Dict, Optional, Any
from flask import Flask, request, jsonify, send_file
from werkzeug.utils import secure_filename

app = Flask(__name__)

ALLOWED_EXTENSIONS = {"mp4", "webm", "mkv", "mov"}
MAX_FILE_SIZE = 2 * 1024 * 1024 * 1024

@dataclass
class TranscriptSegment:
    id: str
    start: float
    end: float
    en_text: str
    hu_text: str = ""
    emotions: List[str] = field(default_factory=list)

@dataclass
class DubbingJob:
    job_id: str
    status: str = "pending"
    created_at: float = field(default_factory=time.time)
    updated_at: float = field(default_factory=time.time)
    video_path: Optional[str] = None
    video_url: Optional[str] = None
    audio_path: Optional[str] = None
    segments: List[TranscriptSegment] = field(default_factory=list)
    tts_audio_path: Optional[str] = None
    localized_audio_path: Optional[str] = None
    fusion_audio_path: Optional[str] = None
    error_message: Optional[str] = None
    progress: int = 0
    current_step: str = "waiting"
    api_keys: Dict[str, str] = field(default_factory=dict)
    settings: Dict[str, Any] = field(default_factory=dict)
    temp_dir: Optional[str] = None

jobs: Dict[str, DubbingJob] = {}

def allowed_file(filename: str) -> bool:
    return "." in filename and filename.rsplit(".", 1)[1].lower() in ALLOWED_EXTENSIONS

def create_temp_dirs() -> str:
    temp_dir = tempfile.mkdtemp(prefix="dubbing_job_")
    os.makedirs(os.path.join(temp_dir, "segments_en"), exist_ok=True)
    os.makedirs(os.path.join(temp_dir, "segments_tts"), exist_ok=True)
    os.makedirs(os.path.join(temp_dir, "segments_loc"), exist_ok=True)
    os.makedirs(os.path.join(temp_dir, "outputs"), exist_ok=True)
    return temp_dir

def cleanup_job(job_id: str) -> None:
    job = jobs.get(job_id)
    if job is not None:
        if job.temp_dir and os.path.isdir(job.temp_dir):
            try:
                shutil.rmtree(job.temp_dir)
            except Exception:
                pass
        jobs.pop(job_id, None)

def update_job_status(job: DubbingJob, status: Optional[str] = None, progress: Optional[int] = None, step: Optional[str] = None, error_message: Optional[str] = None) -> None:
    if status is not None:
        job.status = status
    if progress is not None:
        job.progress = max(0, min(100, progress))
    if step is not None:
        job.current_step = step
    if error_message is not None:
        job.error_message = error_message
    job.updated_at = time.time()

def download_video_to_path(url: str, dest_path: str, job: DubbingJob) -> None:
    update_job_status(job, step="downloading_video")
    with requests.get(url, stream=True, timeout=600) as r:
        r.raise_for_status()
        with open(dest_path, "wb") as f:
            for chunk in r.iter_content(chunk_size=1024 * 1024):
                if chunk:
                    f.write(chunk)

def extract_audio_from_video(video_path: str, audio_path: str, job: DubbingJob) -> None:
    update_job_status(job, step="extracting_audio", progress=5)
    cmd = [
        "ffmpeg",
        "-y",
        "-i",
        video_path,
        "-vn",
        "-acodec",
        "pcm_s16le",
        "-ar",
        "16000",
        "-ac",
        "1",
        audio_path,
    ]
    result = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    if result.returncode != 0:
        raise RuntimeError("FFmpeg audio extraction failed")

def call_openai_stt(audio_path: str, api_key: str, job: DubbingJob) -> List[TranscriptSegment]:
    update_job_status(job, step="stt", progress=10)
    url = ""
    headers = {"Authorization": "Bearer " + api_key}
    with open(audio_path, "rb") as f:
        files = {"file": f}
        data = {
            "model": "gpt-4o-transcribe",
            "response_format": "verbose_json",
            "timestamp_granularities[]": ["segment"],
            "language": "en",
        }
        response = requests.post(url, headers=headers, data=data, files=files, timeout=1800)
    if response.status_code != 200:
        raise RuntimeError("STT provider error: " + response.text)
    payload = response.json()
    segments_json = payload.get("segments", [])
    segments: List[TranscriptSegment] = []
    for i, s in enumerate(segments_json):
        start = float(s.get("start", 0.0))
        end = float(s.get("end", 0.0))
        text = s.get("text", "").strip()
        segment = TranscriptSegment(id=str(i), start=start, end=end, en_text=text)
        segments.append(segment)
    if not segments:
        raise RuntimeError("STT returned no segments")
    update_job_status(job, progress=25)
    return segments

def call_claude_translation(segments: List[TranscriptSegment], api_key: str, job: DubbingJob) -> None:
    update_job_status(job, step="translation", progress=30)
    prompt_header = (
        "Fordítsd le az alábbi angol szegmenseket magyarra. Minden sor egy szegmens.\n"
        "Tartsd meg a stílust és az érzelmeket. Használd a következő jelöléseket:\n"
        "[NEVETÉS], [SZÜNET], [HANGSÚLY], [FELKIÁLTÁS], [KÉRDÉS].\n"
        "Válasz formátuma: pontosan annyi sor, ahány bemeneti szegmens van, "
        "soronként csak a magyar szöveg. Ne írj sorszámot, ne adj magyarázatot.\n\n"
    )
    combined = []
    for idx, seg in enumerate(segments):
        combined.append("Szegmens " + str(idx) + ": " + seg.en_text)
    user_prompt = prompt_header + "\n".join(combined)
    url = ""
    headers = {
        "x-api-key": api_key,
        "anthropic-version": "2023-06-01",
        "content-type": "application/json",
    }
    body = {
        "model": "claude-3-5-sonnet-20241022",
        "max_tokens": 4000,
        "messages": [
            {
                "role": "user",
                "content": user_prompt,
            }
        ],
    }
    response = requests.post(url, headers=headers, json=body, timeout=1800)
    if response.status_code != 200:
        raise RuntimeError("Translator provider error: " + response.text)
    data = response.json()
    content_blocks = data.get("content", [])
    if not content_blocks:
        raise RuntimeError("Translator returned empty content")
    text = ""
    for c in content_blocks:
        if isinstance(c, dict) and c.get("type") == "text":
            text += c.get("text", "")
    lines = [line.strip() for line in text.strip().split("\n") if line.strip() != ""]
    emotion_tokens = {
        "[NEVETÉS]": "laugh",
        "[SZÜNET]": "pause",
        "[HANGSÚLY]": "emphasis",
        "[FELKIÁLTÁS]": "exclamation",
        "[KÉRDÉS]": "question",
    }
    for i, seg in enumerate(segments):
        if i < len(lines):
            hu_text = lines[i]
        else:
            hu_text = seg.en_text
        emotions: List[str] = []
        for token, label in emotion_tokens.items():
            if token in hu_text:
                emotions.append(label)
        seg.hu_text = hu_text
        seg.emotions = emotions
    update_job_status(job, progress=40)

def create_cartesia_voice_clone(audio_path: str, api_key: str) -> str:
    url = ""
    headers = {
        "Authorization": "Bearer " + api_key,
    }
    files = {
        "sample": open(audio_path, "rb"),
    }
    data = {
        "name": "voice-" + str(uuid.uuid4()),
    }
    response = requests.post(url, headers=headers, files=files, data=data, timeout=600)
    files["sample"].close()
    if response.status_code != 200 and response.status_code != 201:
        raise RuntimeError("Cartesia voice clone error: " + response.text)
    payload = response.json()
    voice_id = payload.get("id") or payload.get("voice_id")
    if not voice_id:
        raise RuntimeError("Cartesia returned no voice id")
    return voice_id

def cartesia_tts_segment(text: str, voice_id: str, api_key: str, language: str, emotion: Optional[str]) -> bytes:
    url = ""
    headers = {
        "Authorization": "Bearer " + api_key,
        "Content-Type": "application/json",
    }
    body: Dict[str, Any] = {
        "voice_id": voice_id,
        "text": text,
        "language": language,
        "format": "wav",
    }
    if emotion is not None and emotion != "":
        body["emotion"] = emotion
    response = requests.post(url, headers=headers, json=body, timeout=600)
    if response.status_code != 200:
        raise RuntimeError("Cartesia TTS error: " + response.text)
    return response.content

def load_wav_mono(path: str) -> (np.ndarray, int):
    with wave.open(path, "rb") as wf:
        n_channels = wf.getnchannels()
        sample_width = wf.getsampwidth()
        framerate = wf.getframerate()
        n_frames = wf.getnframes()
        frames = wf.readframes(n_frames)
    if sample_width != 2:
        raise RuntimeError("Only 16-bit PCM WAV is supported")
    audio = np.frombuffer(frames, dtype=np.int16).astype(np.float32) / 32768.0
    if n_channels > 1:
        audio = audio.reshape(-1, n_channels).mean(axis=1)
    return audio, framerate

def save_wav_mono(path: str, audio: np.ndarray, sample_rate: int) -> None:
    audio_clipped = np.clip(audio, -1.0, 1.0)
    int_audio = (audio_clipped * 32767.0).astype(np.int16)
    with wave.open(path, "wb") as wf:
        wf.setnchannels(1)
        wf.setsampwidth(2)
        wf.setframerate(sample_rate)
        wf.writeframes(int_audio.tobytes())

def generate_tts_pipeline(job: DubbingJob) -> None:
    update_job_status(job, step="tts_pipeline", progress=45)
    voice_id = create_cartesia_voice_clone(job.audio_path, job.api_keys["tts"])
    segments_dir = os.path.join(job.temp_dir, "segments_tts")
    os.makedirs(segments_dir, exist_ok=True)
    segment_paths: List[str] = []
    for idx, seg in enumerate(job.segments):
        chosen_emotion = None
        if seg.emotions:
            if "laugh" in seg.emotions:
                chosen_emotion = "excited"
            elif "emphasis" in seg.emotions:
                chosen_emotion = "serious"
            elif "pause" in seg.emotions:
                chosen_emotion = "calm"
            elif "exclamation" in seg.emotions:
                chosen_emotion = "excited"
            elif "question" in seg.emotions:
                chosen_emotion = "curious"
        audio_bytes = cartesia_tts_segment(seg.hu_text, voice_id, job.api_keys["tts"], "hu", chosen_emotion)
        segment_path = os.path.join(segments_dir, "seg_{:05d}.wav".format(idx))
        with open(segment_path, "wb") as f:
            f.write(audio_bytes)
        segment_paths.append(segment_path)
    output_path = os.path.join(job.temp_dir, "outputs", "tts_full.wav")
    concatenate_wavs_by_segments(segment_paths, job.segments, output_path)
    job.tts_audio_path = output_path
    update_job_status(job, progress=65)

def create_resemble_voice(audio_path: str, api_key: str) -> (str, str):
    projects_url = ""
    headers = {
        "Authorization": "Token token=" + api_key,
        "Content-Type": "application/json",
    }
    body = {
        "name": "project-" + str(uuid.uuid4()),
    }
    response = requests.post(projects_url, headers=headers, json=body, timeout=600)
    if response.status_code != 200 and response.status_code != 201:
        raise RuntimeError("Resemble project creation error: " + response.text)
    project_payload = response.json()
    project_uuid = project_payload.get("uuid") or project_payload.get("id")
    if not project_uuid:
        raise RuntimeError("Resemble project id missing")
    voices_url = ""
    voice_body = {
        "name": "voice-" + str(uuid.uuid4()),
        "description": "Source voice profile",
    }
    response = requests.post(voices_url, headers=headers, json=voice_body, timeout=600)
    if response.status_code != 200 and response.status_code != 201:
        raise RuntimeError("Resemble voice creation error: " + response.text)
    voice_payload = response.json()
    voice_uuid = voice_payload.get("uuid") or voice_payload.get("id")
    if not voice_uuid:
        raise RuntimeError("Resemble voice uuid missing")
    clips_url = "" + voice_uuid + "/clips"
    with open(audio_path, "rb") as f:
        files = {
            "file": f,
        }
        data = {
            "name": "training-clip",
            "is_active": "true",
        }
        response = requests.post(clips_url, headers={"Authorization": "Token token=" + api_key}, data=data, files=files, timeout=1800)
    if response.status_code != 200 and response.status_code != 201:
        raise RuntimeError("Resemble training clip error: " + response.text)
    return project_uuid, voice_uuid

def resemble_tts_segment(project_uuid: str, voice_uuid: str, text: str, api_key: str) -> bytes:
    url = "" + project_uuid + "/clips"
    headers = {
        "Authorization": "Token token=" + api_key,
        "Content-Type": "application/json",
    }
    body = {
        "voice_uuid": voice_uuid,
        "text": text,
        "is_active": True,
        "output_format": "wav",
        "sample_rate": 16000,
    }
    response = requests.post(url, headers=headers, json=body, timeout=1800)
    if response.status_code != 200 and response.status_code != 201:
        raise RuntimeError("Resemble clip creation error: " + response.text)
    payload = response.json()
    audio_url = payload.get("audio_src") or payload.get("item", {}).get("audio_src")
    if not audio_url:
        raise RuntimeError("Resemble returned no audio url")
    audio_response = requests.get(audio_url, timeout=600)
    if audio_response.status_code != 200:
        raise RuntimeError("Resemble audio download error")
    return audio_response.content

def generate_localization_pipeline(job: DubbingJob) -> None:
    update_job_status(job, step="localization_pipeline", progress=70)
    project_uuid, voice_uuid = create_resemble_voice(job.audio_path, job.api_keys["localizer"])
    segments_dir = os.path.join(job.temp_dir, "segments_loc")
    os.makedirs(segments_dir, exist_ok=True)
    segment_paths: List[str] = []
    for idx, seg in enumerate(job.segments):
        audio_bytes = resemble_tts_segment(project_uuid, voice_uuid, seg.hu_text, job.api_keys["localizer"])
        segment_path = os.path.join(segments_dir, "seg_{:05d}.wav".format(idx))
        with open(segment_path, "wb") as f:
            f.write(audio_bytes)
        segment_paths.append(segment_path)
    output_path = os.path.join(job.temp_dir, "outputs", "localized_full.wav")
    concatenate_wavs_by_segments(segment_paths, job.segments, output_path)
    job.localized_audio_path = output_path
    update_job_status(job, progress=85)

def concatenate_wavs_by_segments(segment_paths: List[str], segments: List[TranscriptSegment], output_path: str) -> None:
    if not segment_paths:
        raise RuntimeError("No segments to concatenate")
    full_audio_list: List[np.ndarray] = []
    sr_global: Optional[int] = None
    for idx, path in enumerate(segment_paths):
        audio, sr = load_wav_mono(path)
        if sr_global is None:
            sr_global = sr
        elif sr_global != sr:
            raise RuntimeError("Sample rate mismatch in segments")
        target_duration = max(0.0, segments[idx].end - segments[idx].start)
        target_samples = int(target_duration * sr_global)
        if target_samples <= 0:
            target_samples = len(audio)
        if len(audio) < target_samples:
            pad = target_samples - len(audio)
            audio = np.pad(audio, (0, pad), mode="constant", constant_values=0.0)
        elif len(audio) > target_samples:
            audio = audio[:target_samples]
        full_audio_list.append(audio)
    full_audio = np.concatenate(full_audio_list)
    if sr_global is None:
        sr_global = 16000
    save_wav_mono(output_path, full_audio, sr_global)

def fuse_tracks(job: DubbingJob) -> None:
    update_job_status(job, step="fusion", progress=90)
    if job.tts_audio_path is None or job.localized_audio_path is None:
        raise RuntimeError("Missing audio for fusion")
    tts_audio, sr_tts = load_wav_mono(job.tts_audio_path)
    loc_audio, sr_loc = load_wav_mono(job.localized_audio_path)
    if sr_tts != sr_loc:
        raise RuntimeError("Sample rate mismatch between tts and localized")
    length = min(len(tts_audio), len(loc_audio))
    tts_audio = tts_audio[:length]
    loc_audio = loc_audio[:length]
    fused = np.zeros_like(tts_audio)
    n = len(job.segments)
    if n == 0:
        fused = 0.5 * (tts_audio + loc_audio)
    else:
        for idx, seg in enumerate(job.segments):
            start_pos = int(idx * length / n)
            end_pos = int((idx + 1) * length / n)
            if end_pos > length:
                end_pos = length
            tts_seg = tts_audio[start_pos:end_pos]
            loc_seg = loc_audio[start_pos:end_pos]
            if "laugh" in seg.emotions or "emphasis" in seg.emotions or "exclamation" in seg.emotions:
                ratio_tts = 0.2
                ratio_loc = 0.8
            elif "pause" in seg.emotions or "question" in seg.emotions:
                ratio_tts = 0.6
                ratio_loc = 0.4
            else:
                ratio_tts = 0.8
                ratio_loc = 0.2
            mixed = ratio_tts * tts_seg + ratio_loc * loc_seg
            max_val = np.max(np.abs(mixed)) if mixed.size > 0 else 0.0
            if max_val > 0:
                mixed = mixed / max_val * 0.9
            fused[start_pos:end_pos] = mixed
    output_path = os.path.join(job.temp_dir, "outputs", "fusion_full.wav")
    save_wav_mono(output_path, fused, sr_tts)
    job.fusion_audio_path = output_path
    update_job_status(job, progress=100, step="done")

def process_job(job_id: str) -> None:
    job = jobs.get(job_id)
    if job is None:
        return
    try:
        update_job_status(job, status="processing", step="initializing", progress=1)
        if job.video_url:
            video_path = os.path.join(job.temp_dir, "input_video.mp4")
            download_video_to_path(job.video_url, video_path, job)
            job.video_path = video_path
        elif job.video_path and os.path.isfile(job.video_path):
            pass
        else:
            raise RuntimeError("No video source available")
        audio_path = os.path.join(job.temp_dir, "input_audio.wav")
        extract_audio_from_video(job.video_path, audio_path, job)
        job.audio_path = audio_path
        segments = call_openai_stt(job.audio_path, job.api_keys["stt"], job)
        job.segments = segments
        call_claude_translation(job.segments, job.api_keys["translator"], job)
        if not job.settings.get("fusion_enabled", True):
            pass
        generate_tts_pipeline(job)
        generate_localization_pipeline(job)
        fuse_tracks(job)
        update_job_status(job, status="completed", progress=100, step="done")
    except Exception as exc:
        update_job_status(job, status="error", progress=0, step="error", error_message=str(exc))
    timer = threading.Timer(3600.0, cleanup_job, args=(job_id,))
    timer.daemon = True
    timer.start()

@app.route("/create_job", methods=["POST"])
def create_job_endpoint():
    try:
        temp_dir = create_temp_dirs()
        job_id = str(uuid.uuid4())
        settings_raw = None
        if request.form.get("settings"):
            settings_raw = request.form.get("settings")
        elif request.is_json and request.json.get("settings") is not None:
            settings_raw = json.dumps(request.json.get("settings"))
        settings: Dict[str, Any] = {}
        if settings_raw:
            try:
                settings = json.loads(settings_raw)
            except Exception:
                settings = {}
        job = DubbingJob(job_id=job_id, temp_dir=temp_dir, settings=settings)
        file_obj = request.files.get("file")
        video_url = request.form.get("video_url")
        if file_obj:
            filename = secure_filename(file_obj.filename)
            if filename == "":
                shutil.rmtree(temp_dir, ignore_errors=True)
                return jsonify({"error": "No file name"}), 400
            if not allowed_file(filename):
                shutil.rmtree(temp_dir, ignore_errors=True)
                return jsonify({"error": "Invalid file type"}), 400
            content_length = request.content_length
            if content_length is not None and content_length > MAX_FILE_SIZE:
                shutil.rmtree(temp_dir, ignore_errors=True)
                return jsonify({"error": "File too large"}), 400
            video_path = os.path.join(temp_dir, filename)
            file_obj.save(video_path)
            job.video_path = video_path
        elif video_url:
            if not (video_url.startswith("http://") or video_url.startswith("https://")):
                shutil.rmtree(temp_dir, ignore_errors=True)
                return jsonify({"error": "Invalid video URL"}), 400
            job.video_url = video_url
        else:
            shutil.rmtree(temp_dir, ignore_errors=True)
            return jsonify({"error": "No video source provided"}), 400
        jobs[job_id] = job
        return jsonify({"job_id": job_id}), 200
    except Exception as exc:
        return jsonify({"error": str(exc)}), 500

@app.route("/start_dubbing/<job_id>", methods=["POST"])
def start_dubbing_endpoint(job_id: str):
    job = jobs.get(job_id)
    if job is None:
        return jsonify({"error": "Job not found"}), 404
    if not request.is_json:
        return jsonify({"error": "JSON body required"}), 400
    data = request.get_json()
    api_keys = data.get("api_keys") or {}
    required_keys = ["stt", "translator", "tts", "localizer"]
    for key in required_keys:
        if not api_keys.get(key):
            return jsonify({"error": "Missing API key: " + key}), 400
    job.api_keys = {
        "stt": api_keys["stt"],
        "translator": api_keys["translator"],
        "tts": api_keys["tts"],
        "localizer": api_keys["localizer"],
    }
    update_job_status(job, status="queued", step="queued", progress=1)
    t = threading.Thread(target=process_job, args=(job_id,))
    t.daemon = True
    t.start()
    return jsonify({"status": "started", "job_id": job_id}), 200

@app.route("/status/<job_id>", methods=["GET"])
def status_endpoint(job_id: str):
    job = jobs.get(job_id)
    if job is None:
        return jsonify({"error": "Job not found"}), 404
    elapsed = int(time.time() - job.created_at)
    segments_data = [asdict(seg) for seg in job.segments] if job.segments else None
    return jsonify(
        {
            "job_id": job.job_id,
            "status": job.status,
            "progress": job.progress,
            "current_step": job.current_step,
            "elapsed_seconds": elapsed,
            "error_message": job.error_message,
            "segments": segments_data,
        }
    ), 200

@app.route("/download/tts/<job_id>", methods=["GET"])
def download_tts_endpoint(job_id: str):
    job = jobs.get(job_id)
    if job is None:
        return jsonify({"error": "Job not found"}), 404
    if not job.tts_audio_path or not os.path.isfile(job.tts_audio_path):
        return jsonify({"error": "TTS audio not ready"}), 404
    return send_file(job.tts_audio_path, mimetype="audio/wav", as_attachment=True, download_name="tts_hu.wav")

@app.route("/download/localized/<job_id>", methods=["GET"])
def download_localized_endpoint(job_id: str):
    job = jobs.get(job_id)
    if job is None:
        return jsonify({"error": "Job not found"}), 404
    if not job.localized_audio_path or not os.path.isfile(job.localized_audio_path):
        return jsonify({"error": "Localized audio not ready"}), 404
    return send_file(job.localized_audio_path, mimetype="audio/wav", as_attachment=True, download_name="localized_hu.wav")

@app.route("/download/fusion/<job_id>", methods=["GET"])
def download_fusion_endpoint(job_id: str):
    job = jobs.get(job_id)
    if job is None:
        return jsonify({"error": "Job not found"}), 404
    if not job.fusion_audio_path or not os.path.isfile(job.fusion_audio_path):
        return jsonify({"error": "Fusion audio not ready"}), 404
    return send_file(job.fusion_audio_path, mimetype="audio/wav", as_attachment=True, download_name="fusion_hu.wav")

