```python
import os
import uuid
import json
import time
import threading
import tempfile
import subprocess
import requests
import shutil
import wave
import math
import numpy as np
from dataclasses import dataclass, asdict, field
from typing import List, Dict, Optional, Any, Tuple
from flask import Flask, request, jsonify, send_file
from werkzeug.utils import secure_filename

app = Flask(__name__)
app.config["MAX_CONTENT_LENGTH"] = 2 * 1024 * 1024 * 1024

ALLOWED_EXTENSIONS = {"mp4", "webm", "mkv", "mov"}
MAX_FILE_SIZE = 2 * 1024 * 1024 * 1024
MAX_DOWNLOAD_SIZE = 2 * 1024 * 1024 * 1024
JOB_CLEANUP_SECONDS = 3600
DEFAULT_SAMPLE_RATE = 24000

jobs_lock = threading.Lock()
jobs: Dict[str, "DubbingJob"] = {}

@dataclass
class TranscriptSegment:
    id: str
    start: float
    end: float
    en_text: str
    hu_text: str = ""
    emotions: List[str] = field(default_factory=list)

@dataclass
class DubbingJob:
    job_id: str
    status: str = "pending"
    created_at: float = field(default_factory=time.time)
    updated_at: float = field(default_factory=time.time)
    video_path: Optional[str] = None
    video_url: Optional[str] = None
    audio_path: Optional[str] = None
    segments: List[TranscriptSegment] = field(default_factory=list)
    tts_audio_path: Optional[str] = None
    localized_audio_path: Optional[str] = None
    fusion_audio_path: Optional[str] = None
    error_message: Optional[str] = None
    progress: int = 0
    current_step: str = "waiting"
    api_keys: Dict[str, str] = field(default_factory=dict)
    settings: Dict[str, Any] = field(default_factory=dict)
    temp_dir: Optional[str] = None

def allowed_file(filename: str) -> bool:
    return "." in filename and filename.rsplit(".", 1)[1].lower() in ALLOWED_EXTENSIONS

def create_temp_dirs() -> str:
    temp_dir = tempfile.mkdtemp(prefix="dubbing_job_")
    os.makedirs(os.path.join(temp_dir, "segments_en"), exist_ok=True)
    os.makedirs(os.path.join(temp_dir, "segments_tts"), exist_ok=True)
    os.makedirs(os.path.join(temp_dir, "segments_loc"), exist_ok=True)
    os.makedirs(os.path.join(temp_dir, "outputs"), exist_ok=True)
    return temp_dir

def cleanup_job(job_id: str) -> None:
    with jobs_lock:
        job = jobs.get(job_id)
        if job is None:
            return
        temp_dir = job.temp_dir
        jobs.pop(job_id, None)
    if temp_dir and os.path.isdir(temp_dir):
        try:
            shutil.rmtree(temp_dir)
        except Exception:
            pass

def with_job(job_id: str) -> Optional[DubbingJob]:
    with jobs_lock:
        return jobs.get(job_id)

def update_job(job: DubbingJob, status: Optional[str] = None, progress: Optional[int] = None, step: Optional[str] = None, error_message: Optional[str] = None) -> None:
    with jobs_lock:
        if status is not None:
            job.status = status
        if progress is not None:
            job.progress = max(0, min(100, int(progress)))
        if step is not None:
            job.current_step = step
        if error_message is not None:
            job.error_message = error_message
        job.updated_at = time.time()

def download_video_to_path(url: str, dest_path: str, job: DubbingJob) -> None:
    update_job(job, step="downloading_video")
    parsed = url.lower()
    if parsed.startswith("") or parsed.startswith("") or parsed.startswith("") or parsed.startswith("") or parsed.startswith("") or parsed.startswith("") or parsed.startswith("") or parsed.startswith(""):
        raise RuntimeError("URL nem engedélyezett (belső cím).")
    with requests.get(url, stream=True, timeout=(10, 600)) as r:
        r.raise_for_status()
        total = int(r.headers.get("Content-Length") or "0")
        if total and total > MAX_DOWNLOAD_SIZE:
            raise RuntimeError("A letöltendő fájl nagyobb, mint a megengedett maximum.")
        downloaded = 0
        last_update = time.time()
        with open(dest_path, "wb") as f:
            for chunk in r.iter_content(chunk_size=1024 * 1024):
                if not chunk:
                    continue
                f.write(chunk)
                downloaded += len(chunk)
                now = time.time()
                if now - last_update > 2:
                    pct = 3 + int(min(5, downloaded / max(1, total)) * 5) if total else 5
                    update_job(job, progress=pct, step="downloading_video")
                    last_update = now
                if downloaded > MAX_DOWNLOAD_SIZE:
                    raise RuntimeError("A letöltendő fájl meghaladja a megengedett méretet.")

def extract_audio_from_video(video_path: str, audio_path: str, job: DubbingJob) -> None:
    update_job(job, step="extracting_audio", progress=8)
    cmd = [
        "ffmpeg",
        "-y",
        "-i",
        video_path,
        "-vn",
        "-acodec",
        "pcm_s16le",
        "-ar",
        str(DEFAULT_SAMPLE_RATE),
        "-ac",
        "1",
        audio_path,
    ]
    try:
        result = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=1800)
    except subprocess.TimeoutExpired:
        raise RuntimeError("FFmpeg timeout hangkinyerés közben.")
    if result.returncode != 0:
        stderr_text = result.stderr.decode(errors="ignore")
        raise RuntimeError("FFmpeg hiba hangkinyerés közben: " + stderr_text[:4000])

def call_openai_stt(audio_path: str, api_key: str, job: DubbingJob) -> List[TranscriptSegment]:
    update_job(job, step="stt", progress=12)
    url = ""
    headers = {"Authorization": "Bearer " + api_key}
    language = job.settings.get("stt_language") or "en"
    with open(audio_path, "rb") as f:
        files = {"file": f}
        data = {
            "model": "whisper-1",
            "response_format": "verbose_json",
            "language": language,
            "timestamp_granularities[]": "segment",
        }
        response = requests.post(url, headers=headers, data=data, files=files, timeout=3600)
    if response.status_code != 200:
        raise RuntimeError("STT szolgáltató hiba: HTTP " + str(response.status_code))
    try:
        payload = response.json()
    except Exception as exc:
        raise RuntimeError("STT JSON válasz nem értelmezhető: " + str(exc))
    segments_json = payload.get("segments")
    if segments_json is None:
        alt = payload.get("segment", None)
        if isinstance(alt, list):
            segments_json = alt
        else:
            raise RuntimeError("STT válasz nem tartalmaz szegmenslistát.")
    segments: List[TranscriptSegment] = []
    for i, s in enumerate(segments_json):
        try:
            start = float(s.get("start", 0.0))
            end = float(s.get("end", 0.0))
            text = str(s.get("text", "")).strip()
        except Exception:
            continue
        if end < start:
            end = start
        seg = TranscriptSegment(id=str(i), start=start, end=end, en_text=text)
        segments.append(seg)
    if not segments:
        raise RuntimeError("STT nem adott vissza használható szegmenseket.")
    update_job(job, progress=25)
    return segments

def call_claude_translation(segments: List[TranscriptSegment], api_key: str, job: DubbingJob) -> None:
    update_job(job, step="translation", progress=30)
    if not segments:
        raise RuntimeError("Nincsenek szegmensek a fordításhoz.")
    emotion_tokens = {
        "[NEVETÉS]": "laugh",
        "[SZÜNET]": "pause",
        "[HANGSÚLY]": "emphasis",
        "[FELKIÁLTÁS]": "exclamation",
        "[KÉRDÉS]": "question",
    }
    max_batch_segments = 80
    translated_segments: List[str] = []
    for batch_start in range(0, len(segments), max_batch_segments):
        batch = segments[batch_start : batch_start + max_batch_segments]
        header = (
            "Feladat: Angol szegmensek magyarra fordítása, egy sor = egy szegmens.\n"
            "Csak a magyar szöveget add vissza soronként, ugyanannyi sorban, mint amennyi bemeneti szegmens van.\n"
            "Használd a következő jelöléseket (DE ne fordítsd le őket, csak tokenként tartsd meg): [NEVETÉS], [SZÜNET], [HANGSÚLY], [FELKIÁLTÁS], [KÉRDÉS].\n"
            "Bemenet (csak referencia, ne írd vissza a 'Szegmens N:' részt, csak a fordítást add):\n\n"
        )
        lines = []
        for idx, seg in enumerate(batch):
            lines.append("Szegmens " + str(batch_start + idx) + ": " + seg.en_text)
        prompt = header + "\n".join(lines)
        url = ""
        headers = {
            "x-api-key": api_key,
            "anthropic-version": "2023-06-01",
            "content-type": "application/json",
        }
        body = {
            "model": "claude-3-5-sonnet-20241022",
            "max_tokens": 4096,
            "messages": [{"role": "user", "content": prompt}],
        }
        response = requests.post(url, headers=headers, json=body, timeout=3600)
        if response.status_code != 200:
            raise RuntimeError("Claude fordító hiba: HTTP " + str(response.status_code))
        try:
            data = response.json()
        except Exception as exc:
            raise RuntimeError("Claude JSON válasz nem értelmezhető: " + str(exc))
        content_blocks = data.get("content") or []
        text = ""
        for block in content_blocks:
            if isinstance(block, dict) and block.get("type") == "text":
                text += block.get("text") or ""
        lines_out_raw = text.split("\n")
        lines_out: List[str] = []
        current_line = ""
        for raw in lines_out_raw:
            stripped = raw.strip()
            if stripped == "":
                continue
            if current_line == "":
                current_line = stripped
            else:
                if stripped.endswith((".", "?", "!", "…")) or len(stripped) > 5:
                    current_line = current_line + " " + stripped
                else:
                    current_line = current_line + " " + stripped
            if stripped.endswith((".", "!", "?")):
                lines_out.append(current_line.strip())
                current_line = ""
        if current_line.strip() != "":
            lines_out.append(current_line.strip())
        if len(lines_out) < len(batch):
            while len(lines_out) < len(batch):
                lines_out.append(batch[len(lines_out)].en_text)
        elif len(lines_out) > len(batch):
            lines_out = lines_out[: len(batch)]
        translated_segments.extend(lines_out)
        progress_fraction = (batch_start + len(batch)) / max(1, len(segments))
        update_job(job, progress=30 + int(10 * progress_fraction))
    for i, seg in enumerate(segments):
        if i < len(translated_segments):
            hu_text = translated_segments[i]
        else:
            hu_text = seg.en_text
        emotions: List[str] = []
        clean_text = hu_text
        for token, label in emotion_tokens.items():
            if token in clean_text:
                emotions.append(label)
                clean_text = clean_text.replace(token, "").strip()
        seg.hu_text = clean_text
        seg.emotions = emotions
    update_job(job, progress=45)

def create_cartesia_voice_clone(audio_path: str, api_key: str) -> str:
    url = ""
    headers = {
        "X-API-Key": api_key,
    }
    with open(audio_path, "rb") as f:
        files = {"sample": f}
        data = {"name": "voice-" + str(uuid.uuid4())}
        response = requests.post(url, headers=headers, files=files, data=data, timeout=600)
    if response.status_code not in (200, 201):
        raise RuntimeError("Cartesia voice clone hiba: HTTP " + str(response.status_code))
    try:
        payload = response.json()
    except Exception as exc:
        raise RuntimeError("Cartesia voice clone JSON hiba: " + str(exc))
    voice_id = payload.get("id") or payload.get("voice_id")
    if not voice_id:
        raise RuntimeError("Cartesia válasz nem tartalmaz voice ID-t.")
    return voice_id

def cartesia_tts_segment(text: str, voice_id: str, api_key: str, language: str, emotion: Optional[str]) -> bytes:
    url = ""
    headers = {
        "X-API-Key": api_key,
        "Cartesia-Version": "2025-04-16",
        "Content-Type": "application/json",
    }
    body: Dict[str, Any] = {
        "voice_id": voice_id,
        "model": "sonic-2",
        "input": text,
        "language": language,
        "encoding": "pcm_s16le",
        "sample_rate": DEFAULT_SAMPLE_RATE,
        "container": "wav",
        "params": {},
    }
    if emotion:
        body["params"]["emotion"] = [emotion]
    response = requests.post(url, headers=headers, json=body, timeout=600)
    if response.status_code != 200:
        raise RuntimeError("Cartesia TTS hiba: HTTP " + str(response.status_code))
    return response.content

def load_wav_mono(path: str) -> Tuple[np.ndarray, int]:
    with wave.open(path, "rb") as wf:
        n_channels = wf.getnchannels()
        sample_width = wf.getsampwidth()
        framerate = wf.getframerate()
        n_frames = wf.getnframes()
        frames = wf.readframes(n_frames)
    if sample_width == 2:
        audio = np.frombuffer(frames, dtype=np.int16).astype(np.float32) / 32768.0
    elif sample_width == 4:
        audio = np.frombuffer(frames, dtype=np.int32).astype(np.float32) / 2147483648.0
    else:
        raise RuntimeError("Nem támogatott WAV sample width.")
    if n_channels > 1:
        audio = audio.reshape(-1, n_channels).mean(axis=1)
    return audio, framerate

def save_wav_mono(path: str, audio: np.ndarray, sample_rate: int) -> None:
    if audio.size == 0:
        audio = np.zeros(1, dtype=np.float32)
    max_abs = float(np.max(np.abs(audio))) if audio.size > 0 else 0.0
    if max_abs > 1.0:
        audio = audio / max_abs
    clipped = np.clip(audio, -1.0, 1.0)
    int_audio = (clipped * 32767.0).astype(np.int16)
    with wave.open(path, "wb") as wf:
        wf.setnchannels(1)
        wf.setsampwidth(2)
        wf.setframerate(sample_rate)
        wf.writeframes(int_audio.tobytes())

def concatenate_wavs_by_segments(segment_paths: List[str], segments: List[TranscriptSegment], original_duration: float, output_path: str) -> None:
    if not segment_paths or not segments:
        raise RuntimeError("Nincsenek szegmensek az összefűzéshez.")
    audios: List[np.ndarray] = []
    positions: List[Tuple[int, int]] = []
    sample_rate_global: Optional[int] = None
    for idx, path in enumerate(segment_paths):
        try:
            audio, sr = load_wav_mono(path)
        except Exception as exc:
            raise RuntimeError("Hiba a szegmens WAV betöltésekor (" + path + "): " + str(exc))
        if sample_rate_global is None:
            sample_rate_global = sr
        elif sample_rate_global != sr:
            raise RuntimeError("Mintavételi frekvencia eltérés a szegmensek között.")
        seg = segments[idx]
        start_sample = int(seg.start * sample_rate_global)
        end_sample = int(seg.end * sample_rate_global)
        if end_sample < start_sample:
            end_sample = start_sample
        target_len = max(1, end_sample - start_sample)
        if len(audio) < target_len:
            audio = np.pad(audio, (0, target_len - len(audio)), mode="constant", constant_values=0.0)
        elif len(audio) > target_len:
            audio = audio[:target_len]
        audios.append(audio)
        positions.append((start_sample, start_sample + len(audio)))
    if sample_rate_global is None:
        sample_rate_global = DEFAULT_SAMPLE_RATE
    total_length_samples = int(max(original_duration * sample_rate_global, max(end for _, end in positions)))
    full_audio = np.zeros(total_length_samples, dtype=np.float32)
    for (start, end), audio in zip(positions, audios):
        if start >= total_length_samples:
            continue
        slice_end = min(end, total_length_samples)
        length = slice_end - start
        if length <= 0:
            continue
        existing = full_audio[start:slice_end]
        mixed = existing + audio[:length]
        max_val = float(np.max(np.abs(mixed))) if mixed.size > 0 else 0.0
        if max_val > 1.0:
            mixed = mixed / max_val
        full_audio[start:slice_end] = mixed
    save_wav_mono(output_path, full_audio, sample_rate_global)

def generate_tts_pipeline(job: DubbingJob) -> None:
    update_job(job, step="tts_pipeline", progress=50)
    if not job.audio_path:
        raise RuntimeError("Nincs forrás audio a TTS pipeline-hoz.")
    voice_id = create_cartesia_voice_clone(job.audio_path, job.api_keys["tts"])
    segments_dir = os.path.join(job.temp_dir, "segments_tts")
    os.makedirs(segments_dir, exist_ok=True)
    segment_paths: List[str] = []
    for idx, seg in enumerate(job.segments):
        if seg.hu_text.strip() == "":
            continue
        emotion = None
        if "laugh" in seg.emotions:
            emotion = "excited"
        elif "emphasis" in seg.emotions:
            emotion = "serious"
        elif "pause" in seg.emotions:
            emotion = "calm"
        elif "exclamation" in seg.emotions:
            emotion = "excited"
        elif "question" in seg.emotions:
            emotion = "curious"
        audio_bytes = cartesia_tts_segment(seg.hu_text, voice_id, job.api_keys["tts"], "hu", emotion)
        segment_path = os.path.join(segments_dir, "seg_{:05d}.wav".format(idx))
        with open(segment_path, "wb") as f:
            f.write(audio_bytes)
        segment_paths.append(segment_path)
        if len(job.segments) > 0:
            progress_fraction = (idx + 1) / len(job.segments)
            update_job(job, progress=50 + int(10 * progress_fraction))
    duration = 0.0
    if job.segments:
        duration = max(seg.end for seg in job.segments)
    output_path = os.path.join(job.temp_dir, "outputs", "tts_full.wav")
    concatenate_wavs_by_segments(segment_paths, job.segments[: len(segment_paths)], duration, output_path)
    job.tts_audio_path = output_path
    update_job(job, progress=65)

def create_resemble_voice(audio_path: str, api_key: str) -> Tuple[str, str]:
    headers_base = {
        "Authorization": "Token token=" + api_key,
        "Content-Type": "application/json",
    }
    projects_url = ""
    project_body = {"name": "project-" + str(uuid.uuid4())}
    response = requests.post(projects_url, headers=headers_base, json=project_body, timeout=600)
    if response.status_code not in (200, 201):
        raise RuntimeError("Resemble project létrehozási hiba: HTTP " + str(response.status_code))
    try:
        project_payload = response.json()
    except Exception as exc:
        raise RuntimeError("Resemble project JSON hiba: " + str(exc))
    project_uuid = project_payload.get("uuid") or project_payload.get("id")
    if not project_uuid:
        raise RuntimeError("Resemble project UUID hiányzik.")
    voices_url = ""
    voice_body = {"name": "voice-" + str(uuid.uuid4())}
    response = requests.post(voices_url, headers=headers_base, json=voice_body, timeout=600)
    if response.status_code not in (200, 201):
        raise RuntimeError("Resemble voice létrehozási hiba: HTTP " + str(response.status_code))
    try:
        voice_payload = response.json()
    except Exception as exc:
        raise RuntimeError("Resemble voice JSON hiba: " + str(exc))
    voice_uuid = voice_payload.get("uuid") or voice_payload.get("id")
    if not voice_uuid:
        raise RuntimeError("Resemble voice UUID hiányzik.")
    clips_url = "" + voice_uuid + "/recordings"
    with open(audio_path, "rb") as f:
        files = {"file": f}
        data = {"name": "training-clip"}
        response = requests.post(clips_url, headers={"Authorization": "Token token=" + api_key}, data=data, files=files, timeout=1800)
    if response.status_code not in (200, 201, 202):
        raise RuntimeError("Resemble training clip hiba: HTTP " + str(response.status_code))
    return project_uuid, voice_uuid

def resemble_tts_segment(project_uuid: str, voice_uuid: str, text: str, api_key: str) -> bytes:
    url = "" + project_uuid + "/clips"
    headers = {
        "Authorization": "Token token=" + api_key,
        "Content-Type": "application/json",
    }
    body = {
        "voice_uuid": voice_uuid,
        "text": text,
        "is_active": True,
        "output_format": "wav",
        "sample_rate": DEFAULT_SAMPLE_RATE,
    }
    response = requests.post(url, headers=headers, json=body, timeout=1800)
    if response.status_code not in (200, 201):
        raise RuntimeError("Resemble szegmens generálási hiba: HTTP " + str(response.status_code))
    try:
        payload = response.json()
    except Exception as exc:
        raise RuntimeError("Resemble clip JSON hiba: " + str(exc))
    audio_url = payload.get("audio_src") or payload.get("item", {}).get("audio_src")
    if not audio_url:
        raise RuntimeError("Resemble válasz nem tartalmaz audio URL-t.")
    audio_response = requests.get(audio_url, timeout=(10, 600))
    if audio_response.status_code != 200:
        raise RuntimeError("Resemble audio letöltési hiba: HTTP " + str(audio_response.status_code))
    return audio_response.content

def generate_localization_pipeline(job: DubbingJob) -> None:
    update_job(job, step="localization_pipeline", progress=70)
    if not job.audio_path:
        raise RuntimeError("Nincs forrás audio a lokalizációs pipeline-hoz.")
    project_uuid, voice_uuid = create_resemble_voice(job.audio_path, job.api_keys["localizer"])
    segments_dir = os.path.join(job.temp_dir, "segments_loc")
    os.makedirs(segments_dir, exist_ok=True)
    segment_paths: List[str] = []
    for idx, seg in enumerate(job.segments):
        if seg.hu_text.strip() == "":
            continue
        audio_bytes = resemble_tts_segment(project_uuid, voice_uuid, seg.hu_text, job.api_keys["localizer"])
        segment_path = os.path.join(segments_dir, "seg_{:05d}.wav".format(idx))
        with open(segment_path, "wb") as f:
            f.write(audio_bytes)
        segment_paths.append(segment_path)
        if len(job.segments) > 0:
            progress_fraction = (idx + 1) / len(job.segments)
            update_job(job, progress=70 + int(10 * progress_fraction))
    duration = 0.0
    if job.segments:
        duration = max(seg.end for seg in job.segments)
    output_path = os.path.join(job.temp_dir, "outputs", "localized_full.wav")
    concatenate_wavs_by_segments(segment_paths, job.segments[: len(segment_paths)], duration, output_path)
    job.localized_audio_path = output_path
    update_job(job, progress=85)

def fuse_tracks(job: DubbingJob) -> None:
    update_job(job, step="fusion", progress=90)
    if not job.tts_audio_path or not os.path.isfile(job.tts_audio_path):
        raise RuntimeError("Hiányzik a TTS audio a fúzióhoz.")
    if not job.localized_audio_path or not os.path.isfile(job.localized_audio_path):
        raise RuntimeError("Hiányzik a lokalizált audio a fúzióhoz.")
    tts_audio, sr_tts = load_wav_mono(job.tts_audio_path)
    loc_audio, sr_loc = load_wav_mono(job.localized_audio_path)
    if sr_tts != sr_loc:
        raise RuntimeError("Mintavételi frekvencia eltérés a TTS és a lokalizált track között.")
    length = min(len(tts_audio), len(loc_audio))
    tts_audio = tts_audio[:length]
    loc_audio = loc_audio[:length]
    fused = np.zeros(length, dtype=np.float32)
    if not job.segments:
        mix = 0.7 * tts_audio + 0.3 * loc_audio
        max_val = float(np.max(np.abs(mix))) if mix.size > 0 else 0.0
        if max_val > 1.0:
            mix = mix / max_val
        fused[:] = mix
    else:
        max_time = max(seg.end for seg in job.segments)
        if max_time <= 0.0:
            max_time = length / sr_tts
        for seg in job.segments:
            start_sample = int(seg.start / max_time * length)
            end_sample = int(seg.end / max_time * length)
            if end_sample < start_sample:
                end_sample = start_sample
            if start_sample >= length:
                continue
            if end_sample > length:
                end_sample = length
            if end_sample <= start_sample:
                continue
            tts_seg = tts_audio[start_sample:end_sample]
            loc_seg = loc_audio[start_sample:end_sample]
            if "laugh" in seg.emotions or "emphasis" in seg.emotions or "exclamation" in seg.emotions:
                ratio_tts = 0.2
                ratio_loc = 0.8
            elif "pause" in seg.emotions or "question" in seg.emotions:
                ratio_tts = 0.6
                ratio_loc = 0.4
            else:
                ratio_tts = 0.8
                ratio_loc = 0.2
            mixed = ratio_tts * tts_seg + ratio_loc * loc_seg
            max_val = float(np.max(np.abs(mixed))) if mixed.size > 0 else 0.0
            if max_val > 1.2:
                mixed = mixed / max_val
            existing = fused[start_sample:end_sample]
            combined = existing + mixed
            max_comb = float(np.max(np.abs(combined))) if combined.size > 0 else 0.0
            if max_comb > 1.0:
                combined = combined / max_comb
            fused[start_sample:end_sample] = combined
    output_path = os.path.join(job.temp_dir, "outputs", "fusion_full.wav")
    save_wav_mono(output_path, fused, sr_tts)
    job.fusion_audio_path = output_path
    update_job(job, progress=100, step="done")

def get_audio_duration(path: str) -> float:
    with wave.open(path, "rb") as wf:
        frames = wf.getnframes()
        rate = wf.getframerate()
        if rate <= 0:
            return 0.0
        return frames / float(rate)

def process_job(job_id: str) -> None:
    job = with_job(job_id)
    if job is None:
        return
    try:
        update_job(job, status="processing", step="initializing", progress=2)
        if job.video_url:
            video_path = os.path.join(job.temp_dir, "input_video_from_url")
            download_video_to_path(job.video_url, video_path, job)
            job.video_path = video_path
        elif job.video_path and os.path.isfile(job.video_path):
            pass
        else:
            raise RuntimeError("Nincs érvényes videó forrás.")
        audio_path = os.path.join(job.temp_dir, "input_audio.wav")
        extract_audio_from_video(job.video_path, audio_path, job)
        job.audio_path = audio_path
        max_minutes = job.settings.get("max_duration_minutes")
        if isinstance(max_minutes, (int, float)) and max_minutes > 0:
            duration = get_audio_duration(audio_path)
            if duration > max_minutes * 60:
                raise RuntimeError("A videó hossza meghaladja a beállított maximumot.")
        segments = call_openai_stt(job.audio_path, job.api_keys["stt"], job)
        job.segments = segments
        call_claude_translation(job.segments, job.api_keys["translator"], job)
        fusion_enabled = job.settings.get("fusion_enabled", True)
        generate_tts_pipeline(job)
        generate_localization_pipeline(job)
        if fusion_enabled:
            fuse_tracks(job)
        update_job(job, status="completed", progress=100, step="done")
    except Exception as exc:
        update_job(job, status="error", progress=job.progress, step="error", error_message=str(exc))
    timer = threading.Timer(JOB_CLEANUP_SECONDS, cleanup_job, args=(job_id,))
    timer.daemon = True
    timer.start()

@app.route("/create_job", methods=["POST"])
def create_job_endpoint():
    try:
        temp_dir = create_temp_dirs()
        job_id = str(uuid.uuid4())
        settings: Dict[str, Any] = {}
        settings_raw = None
        if request.form.get("settings") is not None:
            settings_raw = request.form.get("settings")
        elif request.is_json:
            try:
                body = request.get_json(silent=True)
            except Exception:
                body = None
            if body and isinstance(body, dict) and body.get("settings") is not None:
                settings_raw = json.dumps(body.get("settings"))
        if settings_raw:
            try:
                settings = json.loads(settings_raw)
            except Exception:
                settings = {}
        video_path: Optional[str] = None
        video_url: Optional[str] = None
        file_obj = request.files.get("file")
        if file_obj and file_obj.filename:
            filename = secure_filename(file_obj.filename)
            if filename == "":
                shutil.rmtree(temp_dir, ignore_errors=True)
                return jsonify({"error": "Üres fájlnév."}), 400
            if not allowed_file(filename):
                shutil.rmtree(temp_dir, ignore_errors=True)
                return jsonify({"error": "Nem támogatott videó formátum."}), 400
            content_length = request.content_length
            if content_length is not None and content_length > MAX_FILE_SIZE:
                shutil.rmtree(temp_dir, ignore_errors=True)
                return jsonify({"error": "A fájl mérete meghaladja a 2 GB-ot."}), 413
            video_path = os.path.join(temp_dir, filename)
            file_obj.save(video_path)
        else:
            video_url_value = request.form.get("video_url")
            if not video_url_value and request.is_json:
                try:
                    body = request.get_json(silent=True)
                except Exception:
                    body = None
                if body and isinstance(body, dict):
                    video_url_value = body.get("video_url")
            if not video_url_value:
                shutil.rmtree(temp_dir, ignore_errors=True)
                return jsonify({"error": "Nem adtál meg videófájlt vagy URL-t."}), 400
            if not (video_url_value.startswith("http://") or video_url_value.startswith("https://")):
                shutil.rmtree(temp_dir, ignore_errors=True)
                return jsonify({"error": "Az URL csak http vagy https lehet."}), 400
            video_url = video_url_value
        job = DubbingJob(job_id=job_id, temp_dir=temp_dir, settings=settings)
        job.video_path = video_path
        job.video_url = video_url
        with jobs_lock:
            jobs[job_id] = job
        return jsonify({"job_id": job_id}), 200
    except Exception as exc:
        return jsonify({"error": str(exc)}), 500

@app.route("/start_dubbing/<job_id>", methods=["POST"])
def start_dubbing_endpoint(job_id: str):
    job = with_job(job_id)
    if job is None:
        return jsonify({"error": "Feladat nem található."}), 404
    if not request.is_json:
        return jsonify({"error": "JSON törzs szükséges."}), 400
    data = request.get_json(silent=True)
    if not data or not isinstance(data, dict):
        return jsonify({"error": "JSON törzs szükséges."}), 400
    api_keys = data.get("api_keys") or {}
    if not isinstance(api_keys, dict):
        return jsonify({"error": "api_keys objektum szükséges."}), 400
    required = ["stt", "translator", "tts", "localizer"]
    for key in required:
        if not api_keys.get(key):
            return jsonify({"error": "Hiányzó API kulcs: " + key}), 400
    job.api_keys = {
        "stt": api_keys["stt"],
        "translator": api_keys["translator"],
        "tts": api_keys["tts"],
        "localizer": api_keys["localizer"],
    }
    update_job(job, status="queued", step="queued", progress=2)
    t = threading.Thread(target=process_job, args=(job_id,))
    t.daemon = True
    t.start()
    return jsonify({"status": "started", "job_id": job_id}), 200

@app.route("/status/<job_id>", methods=["GET"])
def status_endpoint(job_id: str):
    job = with_job(job_id)
    if job is None:
        return jsonify({"error": "Feladat nem található."}), 404
    elapsed = int(time.time() - job.created_at)
    segments_data = [asdict(seg) for seg in job.segments]
    return jsonify(
        {
            "job_id": job.job_id,
            "status": job.status,
            "progress": job.progress,
            "current_step": job.current_step,
            "elapsed_seconds": elapsed,
            "error_message": job.error_message,
            "segments": segments_data,
        }
    ), 200

