@app.route("/download/localized/<job_id>", methods=["GET"])
def download_localized_endpoint(job_id: str):
    job = with_job(job_id)
    if job is None:
        return jsonify({"error": "Feladat nem található."}), 404
    if job.status not in ("completed", "processing"):
        return jsonify({"error": "A lokalizált fájl még nem érhető el."}), 400
    if not job.localized_audio_path or not os.path.isfile(job.localized_audio_path):
        return jsonify({"error": "Lokalizált audio nem készült el."}), 404
    return send_file(job.localized_audio_path, mimetype="audio/wav", as_attachment=True, download_name="localized_hu.wav")

@app.route("/download/fusion/<job_id>", methods=["GET"])
def download_fusion_endpoint(job_id: str):
    job = with_job(job_id)
    if job is None:
        return jsonify({"error": "Feladat nem található."}), 404
    if job.settings.get("fusion_enabled", True) is False:
        return jsonify({"error": "A fúzió ki van kapcsolva ennél a feladatnál."}), 400
    if job.status not in ("completed", "processing"):
        return jsonify({"error": "A fúziós fájl még nem érhető el."}), 400
    if not job.fusion_audio_path or not os.path.isfile(job.fusion_audio_path):
        return jsonify({"error": "Fúziós audio nem készült el."}), 404
    return send_file(job.fusion_audio_path, mimetype="audio/wav", as_attachment=True, download_name="fusion_hu.wav")

if __name__ == "__main__":
    host = os.environ.get("HOST", "0.0.0.0")
    port_str = os.environ.get("PORT", "5000")
    try:
        port = int(port_str)
    except ValueError:
        port = 5000
    app.run(host=host, port=port, debug=False, threaded=True)
