<script>
"use strict";
var backendBaseUrl="";
var currentJobId=null;
var pollingTimer=null;
var selectedFile=null;
var uploadInProgress=false;

function byId(id){return document.getElementById(id);}
function showStep(step){
byId("step1").classList.remove("active");
byId("step2").classList.remove("active");
byId("step3").classList.remove("active");
byId("step4").classList.remove("active");
byId("step"+step).classList.add("active");
}
function showError(id,message){
var box=byId(id);
box.textContent=message;
box.classList.remove("hidden");
}
function clearError(id){
var box=byId(id);
box.textContent="";
box.classList.add("hidden");
}
function loadSettings(){
var maxDuration=localStorage.getItem("maxDurationMinutes");
var fusionEnabled=localStorage.getItem("fusionEnabled");
var keepOriginal=localStorage.getItem("keepOriginalAudio");
var sttLang=localStorage.getItem("sttLanguage");
byId("maxDuration").value=maxDuration?maxDuration:"60";
byId("fusionEnabled").checked=fusionEnabled===null?true:(fusionEnabled==="true");
byId("keepOriginalAudio").checked=keepOriginal==="true";
byId("sttLanguage").value=sttLang||"en";
}
function saveSettings(){
localStorage.setItem("maxDurationMinutes",byId("maxDuration").value||"60");
localStorage.setItem("fusionEnabled",byId("fusionEnabled").checked?"true":"false");
localStorage.setItem("keepOriginalAudio",byId("keepOriginalAudio").checked?"true":"false");
localStorage.setItem("sttLanguage",byId("sttLanguage").value||"en");
}
function openSettings(){
loadSettings();
byId("settingsModal").style.display="flex";
}
function closeSettings(){
byId("settingsModal").style.display="none";
}
function loadApiKeys(){
var keys=["sttKey","translatorKey","ttsKey","localizerKey"];
for(var i=0;i<keys.length;i++){
var k=keys[i];
var v=localStorage.getItem(k);
if(v){byId(k).value=v;}
}
}
function saveApiKeysAndContinue(){
clearError("errorBox1");
var stt=byId("sttKey").value.trim();
var tr=byId("translatorKey").value.trim();
var tts=byId("ttsKey").value.trim();
var loc=byId("localizerKey").value.trim();
if(!stt||!tr||!tts||!loc){
showError("errorBox1","Minden API kulcs megadása szükséges.");
return;
}
localStorage.setItem("sttKey",stt);
localStorage.setItem("translatorKey",tr);
localStorage.setItem("ttsKey",tts);
localStorage.setItem("localizerKey",loc);
showStep(2);
}
function initUploadArea(){
var area=byId("uploadArea");
var fileInput=byId("fileInput");
area.addEventListener("click",function(){
if(uploadInProgress){return;}
fileInput.click();
});
area.addEventListener("dragenter",handleDrag,false);
area.addEventListener("dragover",handleDrag,false);
area.addEventListener("dragleave",handleDragLeave,false);
area.addEventListener("drop",handleDrop,false);
fileInput.addEventListener("change",function(e){
if(e.target.files&&e.target.files.length>0){
handleSelectedFile(e.target.files[0]);
}
});
function handleDrag(e){
e.preventDefault();
e.stopPropagation();
if(uploadInProgress){return;}
area.classList.add("dragover");
}
function handleDragLeave(e){
e.preventDefault();
e.stopPropagation();
area.classList.remove("dragover");
}
function handleDrop(e){
e.preventDefault();
e.stopPropagation();
area.classList.remove("dragover");
if(uploadInProgress){return;}
if(e.dataTransfer.files&&e.dataTransfer.files.length>0){
handleSelectedFile(e.dataTransfer.files[0]);
}
}
}
function handleSelectedFile(file){
clearError("errorBox2");
if(!file){return;}
if(file.size>2*1024*1024*1024){
showError("errorBox2","A fájl nagyobb, mint 2 GB.");
return;
}
selectedFile=file;
byId("fileName").textContent=file.name+" ("+formatBytes(file.size)+")";
byId("fileInfo").classList.remove("hidden");
byId("uploadProgress").style.width="0%";
byId("uploadStatus").textContent="";
byId("startJobButton").disabled=false;
}
function formatBytes(bytes){
if(bytes===0){return"0 B";}
var k=1024;
var sizes=["B","KB","MB","GB","TB"];
var i=Math.floor(Math.log(bytes)/Math.log(k));
return parseFloat((bytes/Math.pow(k,i)).toFixed(2))+" "+sizes[i];
}
function buildSettingsObject(){
var maxMinutes=parseInt(localStorage.getItem("maxDurationMinutes")||"60",10);
var fusionEnabled=localStorage.getItem("fusionEnabled");
var keepOriginal=localStorage.getItem("keepOriginalAudio");
var sttLang=localStorage.getItem("sttLanguage")||"en";
return{
max_duration_minutes:isNaN(maxMinutes)?60:maxMinutes,
fusion_enabled:fusionEnabled===null?true:(fusionEnabled==="true"),
keep_original_audio:keepOriginal==="true",
stt_language:sttLang
};
}
function createJob(){
clearError("errorBox2");
if(!selectedFile&&byId("videoUrl").value.trim()===""){
showError("errorBox2","Válassz videófájlt vagy adj meg URL-t.");
return;
}
var settings=buildSettingsObject();
var formData=new FormData();
formData.append("settings",JSON.stringify(settings));
if(selectedFile){
formData.append("file",selectedFile);
}else{
formData.append("video_url",byId("videoUrl").value.trim());
}
uploadInProgress=true;
byId("startJobButton").disabled=true;
var xhr=new XMLHttpRequest();
xhr.open("POST",backendBaseUrl+"/create_job",true);
xhr.upload.onprogress=function(e){
if(e.lengthComputable){
var percent=e.loaded/e.total*100;
byId("uploadProgress").style.width=percent.toFixed(0)+"%";
byId("uploadStatus").textContent="Feltöltés: "+percent.toFixed(0)+"%";
}
};
xhr.onreadystatechange=function(){
if(xhr.readyState===4){
uploadInProgress=false;
if(xhr.status===200){
var resp=JSON.parse(xhr.responseText);
currentJobId=resp.job_id;
startProcessingOnServer();
}else{
var err="Ismeretlen hiba";
try{
var obj=JSON.parse(xhr.responseText);
if(obj.error){err=obj.error;}
}catch(e){}
showError("errorBox2","Hiba a feladat létrehozásakor: "+err);
byId("startJobButton").disabled=false;
}
}
};
xhr.send(formData);
}
function startProcessingOnServer(){
var apiKeys={
stt:localStorage.getItem("sttKey")||"",
translator:localStorage.getItem("translatorKey")||"",
tts:localStorage.getItem("ttsKey")||"",
localizer:localStorage.getItem("localizerKey")||""
};
fetch(backendBaseUrl+"/start_dubbing/"+encodeURIComponent(currentJobId),{
method:"POST",
headers:{"Content-Type":"application/json"},
body:JSON.stringify({api_keys:apiKeys})
}).then(function(res){
return res.json().then(function(data){return{ok:res.ok,data:data};});
}).then(function(result){
if(!result.ok){
showError("errorBox2","Hiba a feldolgozás indításakor: "+(result.data.error||""));
return;
}
showStep(3);
beginPolling();
}).catch(function(err){
showError("errorBox2","Hálózati hiba: "+err);
});
}
function formatTimeSec(total){
var s=parseInt(total,10);
if(isNaN(s)||s<0){s=0;}
var m=Math.floor(s/60);
var r=s%60;
var mm=(m<10?"0":"")+m;
var ss=(r<10?"0":"")+r;
return mm+":"+ss;
}
function mapStepName(step){
var map={
waiting:"Várakozás",
downloading_video:"Videó letöltése",
extracting_audio:"Hang kinyerése",
stt:"Feliratozás (STT)",
translation:"Fordítás",
tts_pipeline:"TTS generálás",
localization_pipeline:"Hangátvitel generálás",
fusion:"Fúzió",
done:"Kész",
queued:"Sorban áll",
initializing:"Inicializálás",
error:"Hiba"
};
return map[step]||step;
}
function renderSegments(segments){
var box=byId("segmentsBox");
if(!segments||segments.length===0){
box.classList.add("hidden");
box.innerHTML="";
return;
}
var html="";
for(var i=0;i<segments.length;i++){
var seg=segments[i];
html+='<div class="segment-item">';
html+='<div class="segment-time">'+formatTimeSec(seg.start)+" - "+formatTimeSec(seg.end)+"</div>";
html+='<div class="segment-text-en"><strong>EN:</strong> '+escapeHtml(seg.en_text||"")+"</div>";
html+='<div class="segment-text-hu"><strong>HU:</strong> '+escapeHtml(seg.hu_text||"")+"</div>";
if(seg.emotions&&seg.emotions.length>0){
html+='<div class="segment-emotions">';
for(var j=0;j<seg.emotions.length;j++){
var e=seg.emotions[j];
var cls="badge";
if(e==="laugh"){cls+=" laugh";}
else if(e==="emphasis"){cls+=" emphasis";}
else if(e==="pause"){cls+=" pause";}
else if(e==="exclamation"){cls+=" exclamation";}
else if(e==="question"){cls+=" question";}
html+='<span class="'+cls+'">'+e.toUpperCase()+"</span>";
}
html+="</div>";
}
html+="</div>";
}
box.innerHTML=html;
box.classList.remove("hidden");
}
function escapeHtml(text){
return String(text).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;");
}
function updateStatusUI(data){
byId("processProgress").style.width=(data.progress||0)+"%";
byId("progressLabel").textContent=(data.progress||0)+"%";
byId("elapsedLabel").textContent=formatTimeSec(data.elapsed_seconds||0);
byId("stepLabel").textContent=mapStepName(data.current_step||"");
if(data.status==="completed"){
byId("mainStatus").textContent="Kész";
}else if(data.status==="error"){
byId("mainStatus").textContent="Hiba";
}else if(data.status==="processing"||data.status==="queued"){
byId("mainStatus").textContent="Feldolgozás folyamatban…";
}else{
byId("mainStatus").textContent="Ismeretlen állapot";
}
if(data.error_message){
showError("errorBox3",data.error_message);
}
if(data.segments){
renderSegments(data.segments);
}
if(data.status==="completed"){
stopPolling();
prepareDownloads();
showStep(4);
}else if(data.status==="error"){
stopPolling();
}
}
function pollStatusOnce(){
if(!currentJobId){return;}
fetch(backendBaseUrl+"/status/"+encodeURIComponent(currentJobId))
.then(function(res){
return res.json().then(function(data){return{ok:res.ok,data:data};});
})
.then(function(result){
if(!result.ok){
showError("errorBox3",result.data.error||"Ismeretlen hiba");
return;
}
updateStatusUI(result.data);
})
.catch(function(err){
showError("errorBox3","Hálózati hiba: "+err);
});
}
function beginPolling(){
if(pollingTimer){clearInterval(pollingTimer);}
pollStatusOnce();
pollingTimer=setInterval(pollStatusOnce,3000);
}
function stopPolling(){
if(pollingTimer){clearInterval(pollingTimer);pollingTimer=null;}
}
function prepareDownloads(){
if(!currentJobId){return;}
var ttsUrl=backendBaseUrl+"/download/tts/"+encodeURIComponent(currentJobId);
var locUrl=backendBaseUrl+"/download/localized/"+encodeURIComponent(currentJobId);
var fusionUrl=backendBaseUrl+"/download/fusion/"+encodeURIComponent(currentJobId);
byId("audioTts").src=ttsUrl;
byId("audioLoc").src=locUrl;
byId("audioFusion").src=fusionUrl;
byId("dlTtsButton").disabled=false;
byId("dlLocButton").disabled=false;
byId("dlFusionButton").disabled=false;
}
function downloadType(kind){
if(!currentJobId){return;}
var url;
var filename;
if(kind==="tts"){
url=backendBaseUrl+"/download/tts/"+encodeURIComponent(currentJobId);
filename="tts_hu.wav";
}else if(kind==="localized"){
url=backendBaseUrl+"/download/localized/"+encodeURIComponent(currentJobId);
filename="localized_hu.wav";
}else if(kind==="fusion"){
url=backendBaseUrl+"/download/fusion/"+encodeURIComponent(currentJobId);
filename="fusion_hu.wav";
}else{
return;
}
var a=document.createElement("a");
a.href=url;
a.download=filename;
document.body.appendChild(a);
a.click();
document.body.removeChild(a);
}
function resetAll(){
stopPolling();
currentJobId=null;
selectedFile=null;
